module parity_8bit (
    input [7:0] in,
    output out
);

wire w0, w1, w2, w3, w4, w5, w6;

assign w0 = in[1] | in[0];
assign w1 = ~(in[3] | in[2]);
assign w2 = w0 | w1;

assign w3 = in[5] | in[4];
assign w4 = ~(in[7] | in[6]);
assign w5 = w3 | w4;

assign w6 = w2 | w5;
assign out = w6 | in[0];

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire n0, n1, n2, n3, n4, n5, n6, n7, n8, n9;

// Inverter from sel[0]
assign n0 = ~sel[0];

// Left column NAND gates
assign n1 = ~(sel[0] & sel[1]);
assign n2 = ~(in[1] & sel[1]);
assign n3 = ~(in[1] & in[0]);

// Upper branch
assign n4 = ~(sel[0] & sel[1]);
assign n5 = ~(n4 & sel[0]);

// Middle branch
assign n6 = ~(n1 & n0);

// Mux-like block interpreted as 2:1 mux
assign n7 = n0 ? n3 : n2;

// OR chain to output
assign n8 = n6 | n7;
assign out = n8 | n5;

endmodule

module majority (
    input a, b, c,
    output out
);

wire w1, w2, w3, w4;

assign w1 = c & b;
assign w2 = b & a;
assign w3 = w2 | w1;
assign w4 = c & b;
assign out = w3 | w4;

endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

assign gray[0] = binary[1] ^ binary[0];
assign gray[1] = binary[1] ^ binary[0];
assign gray[2] = binary[1] ^ binary[2];
assign gray[3] = binary[2];

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

wire w0, w1, w2, w3, w4, w5, w6;

// Top branch
assign w0 = ~(b[0] ^ a[0]);   // XNOR
assign w1 =  (b[1] ^ a[1]);   // XOR
assign w2 = ~(w0 & w1);               // NAND

// Bottom branch
assign w3 =  (b[2] ^ a[2]);   // XOR
assign w4 =  (b[3] ^ a[3]);   // XOR
assign w5 =  (w3 | w4);               // OR

// Final gate
assign equal = ~(w2 & w5);            // NAND

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

wire a;
assign a = in[0];

assign out[0] = ~(1'b1 | a);
assign out[1] = ~(a & a);
assign out[2] = ~(a & a);
assign out[3] = a & a;

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    code[0] = ~((in[2] & in[3]) | in[3]);
    code[1] = in[3] | in[1];
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

wire n0, n1, n2, n3, n4, n5;
wire q0, q1;

// Left OR gate
assign n0 = clk | reset;

// Top flip-flop connections
assign n1 = ~q0;

// Middle XOR gate
assign n2 = q0 ^ n0;

// Bottom-right NAND gate
assign n3 = ~(q1 & reset);

// Bottom feedback line
assign n4 = n3;

// Output mux/select structure
assign n5 = q0;
assign state[0] = q1 ? n0 : 1'b0;
assign state[1] = 1'b0;

always @(posedge clk or posedge n0) begin
    if (n0)
        q0 <= 1'b0;
    else
        q0 <= clk;
end

always @(posedge n2 or posedge n4) begin
    if (n4)
        q1 <= 1'b0;
    else
        q1 <= q0;
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

wire n0, n1, n2;
wire w0, w1, w2, w3, w4, w5, w6, w7, w8, w9, w10;

// Inputs and basic inversions
assign n0 = ~clk;
assign n1 = ~reset;

// Top-left OR feeding first latch-like stage
assign w0 = reset | n0;

// First stage output
assign w1 = w0;

// NAND into second stage
assign w2 = ~(w1 & reset);

// Second stage output
assign w3 = w2;

// Middle NAND and third stage
assign w4 = ~(w3 & reset);
assign w5 = w4;

// Right-side logic network
assign w6 = ~(w3 & w5);
assign w7 = ~(w6 & w6);
assign w8 = ~(w5 | w5);
assign w9 = ~(w8 & w8);
assign w10 = w8 | w8;

// 3-to-1 style output bus
assign light[0] = w7;
assign light[1] = w9;
assign light[2] = w10;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    wire q0, q1;

    wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12;

    assign q0 = clk;
    assign q1 = reset;

    assign n1  = ~(q0 & down_request);
    assign n2  = ~(down_request | q0);
    assign n3  = ~(n1 & n1);
    assign n4  = ~(n2 & n2);
    assign n5  = ~(n4 & n3);

    assign n6  = ~(q1 | q0);
    assign n7  = ~(up_request | q0);
    assign n8  = ~(q0 & up_request);
    assign n9  = ~(n7 & n8);
    assign n10 = ~(q1 & q0);
    assign n11 = ~(n10 | n9);

    assign n12 = ~(n6 & n5);

    assign state[0] = q1;
    assign state[1] = ~(n12 & n11);

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

wire q0, q1;
wire n1, n2, n3, n4, n5, n6, n7, n8;

// Left flip-flop
assign q0 = reset; // abstracted from diagram connectivity

// Combinational logic
assign n1 = ~(clk | item_selected);
assign n2 = ~(n1 & clk);
assign n3 = ~(coin_inserted | n1);
assign n4 = n3 | n1;
assign n5 = ~(n4 & coin_inserted);

// Upper flip-flop
assign q1 = n2; // abstracted from diagram connectivity

// Output logic
assign n6 = q0 | q1;
assign n7 = ~(n6 | coin_inserted);
assign n8 = ~(q1 | clk);

assign state[1] = q1;
assign state[0] = n7;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

assign out = in_0 ** in_1;

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    assign out = in_0[7:0];
endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    assign out = a + b;
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    assign out = a * b;
endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    assign diff = a + b;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

assign xor_out = a ^ b;
assign and_out = a & b;
assign or_out = a | b;

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    assign out = in << shift;
endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);

assign out[0] = ~in[0];
assign out[1] = ~in[1];
assign out[2] = in[2];
assign out[3] = ~in[3];
assign out[4] = in[4];
assign out[5] = ~in[5];
assign out[6] = ~in[6];
assign out[7] = ~in[7];

endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    assign out = in << shift;
endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

assign out = ~in_0 + 16'sd1;

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

wire w0, w1, w2, w3, w4, w5, w6, w7;
wire n0;

assign w0 = ~(data_in[1] | data_in[4]);
assign w1 = ~(data_in[2] | data_in[4]);
assign w2 =  (w1 | w0);

assign w3 = ~(w2 & data_in[2]);
assign w4 = ~(w2 & data_in[5]);

assign w5 = ~(data_in[6] & data_in[7]);
assign w6 =  (w5 | data_in[0]);
assign w7 = ~(w6 & data_in[1]);

assign n0 = ~data_in[0];

assign data_out[0] = n0;
assign data_out[1] = ~(data_in[1] | data_in[2]);
assign data_out[2] = ~(w0 | w2);
assign data_out[3] =  (w3 | w2);
assign data_out[4] = 1'b0;
assign data_out[5] = ~(w4 | w2);
assign data_out[6] = ~(data_in[4] | data_in[5]);
assign data_out[7] =  (w7 | data_in[0]);

endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    wire w_and_top;
    wire w_xnor_mid;
    wire w_or_mid;

    wire w_nand1;
    wire w_nor1;
    wire w_nand2;
    wire w_nand3;
    wire w_nand4;

    wire w_nand5;
    wire w_or_bot;
    wire w_nand6;

    assign w_and_top = data_in[1] & data_in[2];

    assign data_out[0] = ~(data_in[0]);
    assign data_out[1] = data_in[0] ^ data_in[1];
    assign data_out[2] = ~(w_and_top ^ data_in[4]);

    assign w_or_mid = w_and_top | data_in[5];
    assign data_out[3] = w_or_mid ^ data_in[6];

    assign data_out[4] = ~(data_in[5] ^ data_in[6]);

    assign w_nand1 = ~(data_in[6] & data_in[7]);
    assign w_nor1  = ~(data_in[6] | data_in[7]);
    assign w_nand2 = ~(w_nor1 & data_in[1]);
    assign w_nand3 = ~(w_nand1 & w_nand2);

    assign w_nand4 = ~(w_nand3 & data_in[5]);
    assign data_out[5] = w_nand4 ^ w_nand3;

    assign data_out[6] = ~(data_in[4] ^ w_nand3);

    assign w_nand5 = ~(data_in[6] & data_in[7]);
    assign w_or_bot = w_nand5 | data_in[0];
    assign w_nand6 = ~(w_or_bot & data_in[0]);
    assign data_out[7] = w_nand6 ^ data_in[7];

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire w0, w1, w2, w3;
    wire [7:0] out_bus;

    assign w0 = data_in[0] ^ data_in[4];
    assign w1 = ~(data_in[1] ^ data_in[5]);
    assign w2 = data_in[2] ^ data_in[6];
    assign w3 = ~(data_in[3] ^ data_in[7]);

    assign out_bus[3:0] = {w3, w2, w1, w0};
    assign out_bus[7:4] = 4'b0000;

    assign data_out = out_bus;

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

wire q;

SDFF_PP0_ ff (
    .C(clk),
    .D(rst),
    .R(rst),
    .Q(q)
);

assign clk_out = q;

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

wire w0, w1, w2, w3, w4, w5, w6, w7;

// Split in bus
assign w0 = in[0];
assign w1 = in[1];

// Inverter on in[1]
assign w2 = ~w1;

// NOR gate: inputs in[1] and enable
assign w3 = ~(w1 | enable);

// NAND gate: inputs in[1] and inverted in[1]
assign w4 = ~(w1 & w2);

// NAND gate: inputs inverted in[1] and NOR output
assign w5 = ~(w2 & w3);

// NAND gate: inputs NOR output and enable
assign w6 = ~(w3 & enable);

// NAND gate: inputs enable and enable
assign w7 = ~(enable & enable);

// Output bus assembly
assign out[0] = w5;
assign out[1] = w4;
assign out[2] = w6;
assign out[3] = ~(w7 & enable);

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);

wire a, b, c;
wire n0, n1, n2, n3, n4;

assign a = in[1];
assign b = in[0];
assign c = enable;

assign n0 = ~a;
assign n1 = ~(b | c);
assign n2 = ~(b & c);
assign n3 = ~(n0 & n1);
assign n4 = ~(n0 & n2);

assign out[0] = n3;
assign out[1] = n4;
assign out[2] = 1'b0;
assign out[3] = ~(n2 & n2);
assign out[7:4] = 4'b0000;

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

assign out1 = in & sel;
assign out0 = ~(in & sel);

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

assign out1 = in & sel[0];
assign out0 = ~(in & sel[0]);
assign out2 = 1'b0;
assign out3 = 1'b0;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

assign count = {6'b000000, clk, rst};

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

wire n0;
wire q0, q1, q2, q3;

assign n0 = ~clk;

dff_sr ff0 (
    .c(clk),
    .d(n0),
    .r(rst),
    .q(q0)
);

dff_sr ff1 (
    .c(clk),
    .d(q0),
    .r(rst),
    .q(q1)
);

dff_sr ff2 (
    .c(clk),
    .d(q1),
    .r(clk),
    .q(q2)
);

dff_sr ff3 (
    .c(clk),
    .d(q2),
    .r(q2),
    .q(q3)
);

assign q[0] = q3;
assign q[1] = q2;
assign q[2] = q1;
assign q[3] = q1;

endmodule

module dff_sr (
    input c,
    input d,
    input r,
    output reg q
);
always @(posedge c or posedge r) begin
    if (r)
        q <= 1'b0;
    else
        q <= d;
end
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

wire n0;
assign n0 = ~(rst | pin[0]);

reg q0, q1, q2, q3, q4, q5, q6, q7;

always @(posedge clk or posedge load) begin
    if (load)
        q0 <= 1'b0;
    else
        q0 <= n0;
end

always @(posedge clk or posedge load) begin
    if (load)
        q1 <= 1'b0;
    else
        q1 <= q0;
end

always @(posedge clk or posedge load) begin
    if (load)
        q2 <= 1'b0;
    else
        q2 <= q1;
end

always @(posedge clk or posedge load) begin
    if (load)
        q3 <= 1'b0;
    else
        q3 <= q2;
end

always @(posedge clk or posedge load) begin
    if (load)
        q4 <= 1'b0;
    else
        q4 <= q3;
end

always @(posedge clk or posedge load) begin
    if (load)
        q5 <= 1'b0;
    else
        q5 <= q4;
end

always @(posedge clk or posedge load) begin
    if (load)
        q6 <= 1'b0;
    else
        q6 <= q5;
end

always @(posedge clk or posedge load) begin
    if (load)
        q7 <= 1'b0;
    else
        q7 <= q6;
end

assign sout = q7;

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);

wire w_top_and_n;
wire w_top_or;
wire w_mid_or;
wire w_bot_or;

assign w_top_and_n = ~(in[0] & in[2]);
assign w_top_or    = w_top_and_n | in[3];
assign w_mid_or    = in[1] | in[2];
assign w_bot_or    = in[0] | in[3];

assign out[0] = w_top_or;
assign out[1] = w_mid_or;
assign valid    = w_mid_or | w_bot_or;

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

wire q0, q1, q2, q3;

reg r_q0, r_q1, r_q2, r_q3;

always @(posedge clk or posedge rst) begin
    if (rst)
        r_q0 <= 1'b0;
    else
        r_q0 <= rst;
end

always @(posedge clk or posedge q0) begin
    if (q0)
        r_q1 <= 1'b0;
    else
        r_q1 <= rst;
end

always @(posedge clk or posedge rst) begin
    if (rst)
        r_q2 <= 1'b0;
    else
        r_q2 <= q1;
end

always @(posedge q2 or posedge q1) begin
    if (q1)
        r_q3 <= 1'b0;
    else
        r_q3 <= rst;
end

assign q0 = r_q0;
assign q1 = r_q1;
assign q2 = r_q2;
assign q3 = r_q3;

assign q[0] = clk;
assign q[1] = q2;
assign q[2] = q3;
assign q[3] = q1;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

wire q0, q1, q2, q3, q4, q5, q6, q7;

S_SDFF_PP0_ ff0 (.C(sin), .D(q0), .R(clk), .Q(q0));
S_SDFF_PP0_ ff1 (.C(q0),    .D(sin), .R(clk), .Q(q1));
S_SDFF_PP0_ ff2 (.C(q1),    .D(sin), .R(clk), .Q(q2));
S_SDFF_PP0_ ff3 (.C(q2),    .D(sin), .R(clk), .Q(q3));
S_SDFF_PP0_ ff4 (.C(q3),    .D(sin), .R(clk), .Q(q4));
S_SDFF_PP0_ ff5 (.C(q4),    .D(sin), .R(clk), .Q(q5));
S_SDFF_PP0_ ff6 (.C(q5),    .D(sin), .R(clk), .Q(q6));
S_SDFF_PP0_ ff7 (.C(q6),    .D(sin), .R(rst), .Q(q7));

assign pout[0] = q0;
assign pout[1] = q1;
assign pout[2] = q2;
assign pout[3] = q3;
assign pout[4] = q4;
assign pout[5] = q5;
assign pout[6] = q6;
assign pout[7] = q7;

endmodule

module S_SDFF_PP0_(
    input C,
    input D,
    input R,
    output reg Q
);
always @(posedge C or posedge R) begin
    if (R)
        Q <= 1'b0;
    else
        Q <= D;
end
endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);

wire q0, q1, q2, q3, q4, q5, q6;

SDFF_PP0 s0 (.C(clk), .D(sin), .R(rst), .Q(q0));
SDFF_PP0 s1 (.C(clk), .D(q0),    .R(rst), .Q(q1));
SDFF_PP0 s2 (.C(clk), .D(q1),    .R(rst), .Q(q2));
SDFF_PP0 s3 (.C(clk), .D(q2),    .R(rst), .Q(q3));
SDFF_PP0 s4 (.C(clk), .D(q3),    .R(rst), .Q(q4));
SDFF_PP0 s5 (.C(clk), .D(q4),    .R(rst), .Q(q5));
SDFF_PP0 s6 (.C(clk), .D(q5),    .R(rst), .Q(q6));

assign sout = q6;

endmodule

module SDFF_PP0(
    input C,
    input D,
    input R,
    output reg Q
);
    always @(posedge C or posedge R) begin
        if (R)
            Q <= 1'b0;
        else
            Q <= D;
    end
endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

assign count = 8'b00000000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  wire a0, a1, a2;
  assign a0 = r[0];
  assign a1 = r[1];
  assign a2 = r[2];

  wire n0, n1, n2, n3, n4, n5, n6, n7, n8, n9;
  wire n10, n11, n12, n13, n14, n15, n16, n17, n18, n19;
  wire n20, n21, n22, n23, n24, n25, n26, n27, n28, n29;
  wire n30, n31, n32, n33, n34, n35, n36, n37, n38, n39;
  wire n40, n41, n42, n43, n44, n45, n46, n47, n48, n49;
  wire n50, n51, n52, n53, n54, n55, n56, n57, n58, n59;

  assign n0  = ~resetn;
  assign n1  = ~(a1 | a0);
  assign n2  = ~(a2 & resetn);
  assign n3  = a1 & n0;
  assign n4  = ~(a0 | clk);
  assign n5  = ~(n3 & n4);
  assign n6  = ~(a2 & a0);
  assign n7  = ~(n5 & n6);
  assign n8  = ~(a1 | clk);
  assign n9  = ~(a2 & n8);
  assign n10 = ~(n7 | n9);
  assign n11 = ~(a0 & clk);
  assign n12 = ~(a1 & n11);
  assign n13 = ~(a2 & clk);
  assign n14 = ~(n12 & n13);
  assign n15 = n14 | n10;
  assign n16 = ~(a2 | n15);
  assign n17 = ~(n1 | n16);
  assign n18 = ~(a1 | n17);
  assign n19 = ~(n17 & n0);
  assign n20 = ~a2;
  assign n21 = ~(n20 & n17);
  assign n22 = ~(n19 & n21);
  assign n23 = ~(n18 | n22);

  assign n24 = ~(a0 & n0);
  assign n25 = ~(a1 & a2);
  assign n26 = ~(n24 & n25);
  assign n27 = ~(a0 & a1);
  assign n28 = ~(n26 & n27);
  assign n29 = n28 | clk;
  assign n30 = ~(a2 | resetn);
