module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  reg q0, q1, q2, q3;

  wire n0, n1;
  wire or_left;
  wire and_mid;
  wire xor_mid;
  wire mux_mid;
  wire nand_a, nand_b;
  wire nor_low;
  wire nand_top;
  wire xor_top;
  wire nor_right;
  wire mux_right1, mux_right2;

  assign n0 = ~clk;
  assign n1 = ~count_ena;

  assign or_left  = shift_ena | count_ena;
  assign and_mid  = clk & q0;
  assign xor_mid  = n0 ^ and_mid;
  assign mux_mid  = and_mid ? xor_mid : q1;

  assign nand_a   = ~(count_ena & q0);
  assign nand_b   = ~(count_ena & shift_ena);
  assign nor_low  = ~(nand_a | nand_b);

  assign nand_top = ~(q3 & clk);
  assign xor_top  = nand_top ^ q3;

  assign nor_right = ~(q1 | nor_low);
  assign mux_right1 = q2 ? nor_right : q1;
  assign mux_right2 = data ? n1 : mux_right1;

  always @(posedge clk) begin
    if (or_left)
      q0 <= clk;
    if (or_left)
      q1 <= q0;
    if (nor_low)
      q2 <= mux_mid;
    if (mux_right1)
      q3 <= q2;
  end

  always @(*) begin
    q[0] = clk;
    q[1] = q1;
    q[2] = q2;
    q[3] = mux_right2;
  end

endmodule

