  wire d0, d1, d2, d3;
  wire en2;

  assign rst_n = areset | ena | load;

  assign d0 = data[3] & rst_n;
  assign d1 = data[2];
  assign d2 = data[1];
  assign d3 = data[0];

  assign en2 = areset;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      q0 <= 1'b0;
    else
      q0 <= d0;
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      q1 <= 1'b0;
    else
      q1 <= d1;
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      q2 <= 1'b0;
    else if (en2)
      q2 <= d2;
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      q3 <= 1'b0;
    else
      q3 <= d3;
  end

  always @(*) begin
    q[0] = q0;
    q[1] = q1;
    q[2] = q2;
    q[3] = q3;
  end

endmodule

