  assign next_state[1] = ~(bus_ctrl & bus_ctrl);
  assign next_state[2] =  (bus_ctrl & state[5]);
  assign next_state[3] =  (bus_ctrl & state[6]);
  assign next_state[4] =  (bus_ctrl & state[4]);
  assign next_state[5] =  (bus_ctrl & in);
  assign next_state[6] =  (bus_ctrl & state[3]);
  assign next_state[7] = ~(low_nor & bus_ctrl);
  assign next_state[8] = ~(bus_ctrl & state[2]);
  assign next_state[9] = ~(bus_ctrl & state[9]);

  assign out2 = state[0] | state[1];
  assign out1 = state[2] | state[3];

