module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

wire [7:0] p;
wire [7:0] g;
wire [8:0] c;

assign p = a ^ b;
assign g = a & b;

assign c[0] = cin;
assign c[1] = g[0] | (p[0] & c[0]);
assign c[2] = g[1] | (p[1] & c[1]);
assign c[3] = g[2] | (p[2] & c[2]);
assign c[4] = g[3] | (p[3] & c[3]);
assign c[5] = g[4] | (p[4] & c[4]);
assign c[6] = g[5] | (p[5] & c[5]);
assign c[7] = g[6] | (p[6] & c[6]);
assign c[8] = g[7] | (p[7] & c[7]);

assign sum = p ^ c[7:0];
assign cout = c[8];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

wire [4:0] bin_sum;
wire correction;
wire [4:0] bcd_sum;

assign bin_sum = A + B + Cin;
assign correction = bin_sum[4] | (bin_sum[3] & (bin_sum[2] | bin_sum[1]));
assign bcd_sum = bin_sum + (correction ? 5'd6 : 5'd0);

assign Sum = bcd_sum[3:0];
assign Cout = correction;

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12, n13, n14, n15;

// Top branch
assign n1  = ~(B[2] ^ B[1]);          // XNOR
assign n2  = ~(B[2] | B[1] | B[0]); // NOR

// Middle-left logic
assign n3  = ~(B[1] | A[2]);          // NOR
assign n4  = ~(A[0] | A[1]);          // NOR
assign n5  = ~(n4 & A[0]);                // NAND
assign n6  = ~(n3 & n5);                      // NAND

// Lower-left logic
assign n7  = A[0] ^ B[0];             // XOR
assign n8  = n7 ^ n5;                         // XOR
assign n9  = n8 | A[0];                   // OR

// Center logic
assign n10 = ~(n6 & n1);                      // NAND
assign n11 = ~(n10 & n2);                     // NAND

// Right-side outputs
assign A_less = n11;
assign n12 = ~(n11 & n11);                    // NAND as inverter/buffered complement
assign A_greater = ~(n12 | n12);                  // NOR as inverter
assign n13 = ~(n9 & n10);                     // NAND
assign A_equal = n13;

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10;
wire n11, n12, n13, n14, n15, n16, n17, n18, n19, n20;
wire n21, n22, n23, n24, n25, n26, n27, n28, n29, n30;
wire n31, n32, n33, n34, n35, n36, n37, n38, n39, n40;

// Upper-left logic
assign n1  = ~(B[3] & B[2]);            // NAND
assign n2  = ~(B[3] ^ A[3]);            // XNOR
assign n3  = ~(B[2] | n1);                  // NOR
assign n4  = ~(n2 | n1);                        // NOR
assign n5  = ~(n3 & n4);                        // NAND

// Top path
assign n6  = ~(B[3] ^ B[2]);            // XNOR
assign n7  =  (n1 ^ n6);                        // XOR
assign n8  = ~(n7 & n6);                        // NAND

// Mid-upper logic
assign n9  = ~(n5 | B[1]);                  // NOR
assign n10 = ~(n9 | n5);                        // NOR
assign n11 =  (n10 ^ n5);                       // XOR
assign n12 =  (n5 ^ B[1]);                  // XOR
assign n13 =  (n11 | n12);                      // OR
assign n14 = ~(n13 & n8);                       // NAND

// Lower-middle logic
assign n15 =  (A[2] ^ A[1]);            // XOR
assign n16 = ~(A[0] | n15);                 // NOR
assign n17 =  (n16 ^ n10);                      // XOR
assign n18 = ~(n17 & B[1]);                 // NAND
assign n19 = ~(n17 & n16);                      // NAND
assign n20 =  (n18 | n19);                      // OR
assign n21 = ~(B[0] & A[3]);            // NAND
assign n22 =  (n20 | n21);                      // OR
assign n23 = ~(n22 | B[1]);                 // NOR

// Final stage
assign A_less = n23;
assign A_greater = ~(n14 | A_less);                  // NOR
assign A_equal = A_greater;

endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  reg q0, q1, q2, q3;

  wire n1, n2, n3, n4, n5, n6, n7, n8, n9;
