  assign n1 = ~(q1 & q0);
  assign n2 = ~(q2 | q3);
  assign n3 = ~(q2 | q1);
  assign n4 = n2 | n1;
  assign n5 = n3 ^ q2;
  assign n6 = n3 | q3;
  assign n7 = n6 ^ n5;
  assign n8 = ~(n4 & n5);
  assign n9 = ~(n7 & n8);

  assign d0 = q0 ^ q1;
  assign d1 = n1;
  assign d2 = n9;
  assign d3 = n8;

  always @(posedge clk or posedge rst_n or posedge valid_count) begin
    if (rst_n) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
    end else if (valid_count) begin
      q0 <= q0;
      q1 <= q1;
      q2 <= q2;
      q3 <= q3;
    end else begin
      q0 <= d0;
      q1 <= d1;
      q2 <= d2;
      q3 <= d3;
    end
  end

  always @(*) begin
    out[0] = q1;
    out[1] = q1;
    out[2] = n4;
    out[3] = q2;
  end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

	reg q0;

	always @(*) begin
		if (rst_n)
			q0 = 1'b0;
		else if (clk)
			q0 = a;
	end

	always @(*) begin
		if (rst_n)
			rise = 1'b0;
		else if (clk)
			rise = ~(q0 & clk);
	end

	always @(*) begin
		if (rst_n)
			down = 1'b0;
		else if (clk)
			down = ~(q0 & rst_n);
	end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg q0, q1, q2, q3, q4;
    reg [NUM_DIV-1:0] divcnt;

    wire n0, n1, n2, n3, n4, n5, n6, n7, n8, n9;
    wire clk_div;

    assign clk_div = divcnt[NUM_DIV-1];

    assign n0 = ~(q0 | rst_n);
    assign n1 = ~(n0 & q1);
    assign n2 = q1 | q2;
    assign n3 = ~(q2 & rst_n);
    assign n4 = q3 | n3;
    assign n5 = ~(n4 & clk);
    assign n6 = ~(q2 & n3);
    assign n7 = ~(q4 & clk);
    assign n8 = ~q3;
    assign n9 = n8 | q4;

    always @(posedge clk or posedge rst_n) begin
        if (rst_n)
            divcnt <= {NUM_DIV{1'b0}};
        else
            divcnt <= divcnt + {{(NUM_DIV-1){1'b0}},1'b1};
    end

    always @(posedge clk_div or posedge rst_n) begin
        if (rst_n) begin
            q0 <= 1'b0;
            q1 <= 1'b0;
            q2 <= 1'b0;
            q3 <= 1'b0;
            q4 <= 1'b0;
            clk_div <= 1'b0;
        end else begin
            q0 <= ~(clk & q4 & q0);
            q1 <= n1;
            q2 <= clk;
            q3 <= n6;
            q4 <= n7;
            clk_div <= n9;
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

reg [14:0] q;

wire clk = clk;
wire en  = rst;
wire rst = ~(fetch[1] | fetch[0]);

always @(posedge clk or posedge rst) begin
    if (rst)
        q <= 15'b0;
    else if (en) begin
        q[0]  <= clk;
        q[1]  <= rst;
        q[2]  <= data[0];
        q[3]  <= data[1];
        q[4]  <= data[2];
        q[5]  <= data[3];
        q[6]  <= data[4];
        q[7]  <= data[5];
        q[8]  <= data[6];
        q[9]  <= data[7];
        q[10] <= data[0];
        q[11] <= data[1];
        q[12] <= data[2];
        q[13] <= data[3];
        q[14] <= data[4];
    end
end

assign ins = {q[9], q[8], q[0]};
assign ad2 = {q[14], q[7], q[6], q[5], q[4], q[3], q[2], q[1]};
assign ad1 = {q[14], q[13], q[12], q[11], q[10]};

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  reg q0, q1, q2, q3;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
    end else begin
      q0 <= 1'b1;
      q1 <= q0;
      q2 <= ~(q1 | clk);
      q3 <= q2;
    end
  end

  always @(*) begin
    out[0] = q2;
    out[1] = q0;
    out[2] = q3;
    out[3] = rst;
  end

endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input d;  
    output  [7:0] q;

    reg [7:0] q;

    always @(posedge clk) begin
        q[7] <= d;
        q[6] <= q[7];
        q[5] <= q[6];
        q[4] <= q[5];
        q[3] <= q[4];
        q[2] <= q[3];
        q[1] <= q[2];
        q[0] <= q[1];
    end

    assign q = q;

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg q_a, q_b, q_c, q_d, q_e, q_f;
reg q6_0, q6_1, q6_2, q6_3;

always @(posedge clk_a or posedge arstn) begin
	if (arstn)
		q_a <= 1'b0;
	else
		q_a <= data_en;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q_b <= 1'b0;
	else
		q_b <= clk_b;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q_c <= 1'b0;
	else
		q_c <= q_a;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q_d <= 1'b0;
	else
		q_d <= data_in[1];
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q_e <= 1'b0;
	else
		q_e <= data_in[3];
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q_f <= 1'b0;
	else
		q_f <= arstn;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q6_0 <= 1'b0;
	else if (clk_b)
		q6_0 <= q_c;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q6_1 <= 1'b0;
	else if (clk_b)
		q6_1 <= q_b;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q6_2 <= 1'b0;
	else if (clk_b)
		q6_2 <= q_d;
end

always @(posedge clk_a or posedge brstn) begin
	if (brstn)
		q6_3 <= 1'b0;
	else if (clk_b)
		q6_3 <= q_e;
end

always @(*) begin
	dataout[0] = q6_0;
	dataout[1] = q6_1;
	dataout[2] = q6_2;
	dataout[3] = q6_3;
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg q0, q1, q2, q3, q4, q5;

wire n0, n1, n2, n3, n4, n5, n6, n7, n8, n9;
wire d0, d1, d2, d3, d4, d5;
wire r0, r1, r2, r3, r4, r5;

assign n0 = ~IN;
assign n1 = ~CLK;
assign n2 = ~(IN & CLK);
assign n3 = ~(q1 | q2);
assign n4 = ~(q2 & n1);
assign n5 = (q1 | q3);
assign n6 = ~(n0);
assign n7 = ~(q0 & n6);
assign n8 = (q2 | q4);
assign n9 = ~((n8 | n5) | n4);

assign r0 = CLK;
assign d0 = RST;

assign r1 = CLK;
assign d1 = ~n2;

assign r2 = n7;
assign d2 = ~(n3 & n6);

assign r3 = q0;
assign d3 = q2;

assign r4 = q0;
assign d4 = n9;

assign r5 = q0;
assign d5 = ~(q4 & ((n5 | n4) | (q3 | n7)));

always @(*) begin
    if (r0)
        q0 = 1'b0;
    else if (CLK)
        q0 = d0;

    if (r1)
        q1 = 1'b0;
    else if (CLK)
        q1 = d1;

    if (r2)
        q2 = 1'b0;
    else if (n1)
        q2 = d2;

    if (r3)
        q3 = 1'b0;
    else if (RST)
        q3 = d3;

    if (r4)
        q4 = 1'b0;
    else if (q3)
        q4 = d4;

    if (r5)
        q5 = 1'b0;
    else if (q4)
        q5 = d5;

    MATCH = q5;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

wire q0, q1, q2, q3, q4, q5, q6;
wire n1, n2, n3, n4, n5;
wire d3, d4, d5, d6;

assign n1 = ~(q1 & q0);
assign n2 = ~(n1 & n1);
assign n3 = q0 & d[1];
assign d3 = q2 ? n3 : q0;
assign d4 = q3 ? q4 : d[2];
assign d5 = q2 ? q3 : d[3];
assign d6 = q5 ? q4 : d[0];
assign n4 = ~(q0 & q0);
assign n5 = n4 | q0;

assign valid_out = q6;
assign dout = q5;

always @(posedge clk or posedge rst_n) begin
    if (rst_n) begin
        q0 <= 1'b0;
        q1 <= 1'b0;
        q2 <= 1'b0;
        q3 <= 1'b0;
        q4 <= 1'b0;
        q5 <= 1'b0;
        q6 <= 1'b0;
    end else begin
        q0 <= n5;
        q1 <= q0;
        q2 <= n2;
        q3 <= d3;
        q4 <= d4;
        q5 <= d5;
        q6 <= d6;
    end
end

endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);

always @(*) begin
    case (addr)
        8'd0: dout = 16'b0000000000000001;
        8'd1: dout = 16'b0011001100110010;
        default: dout = 16'b0001000100010000;
    endcase
end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

wire q0, q1, q2, q3;
wire d0, d1, d2, d3;

assign d0 = ~(clk & rst_n);
assign d1 = ~(q0 & rst_n);
assign d2 = q1 & data_in;
assign d3 = ~((q2 | rst_n) & data_in);

assign sequence_detected = q3;

reg r0, r1, r2, r3;

always @(*) begin
    r0 = q3;
    r1 = q0;
    r2 = clk;
    r3 = sequence_detected;
end

reg q0_reg, q1_reg, q2_reg, q3_reg;

assign q0 = q0_reg;
assign q1 = q1_reg;
assign q2 = q2_reg;
assign q3 = q3_reg;

always @(posedge clk or posedge r0) begin
    if (r0)
        q0_reg <= 1'b0;
    else
        q0_reg <= d0;
end

always @(posedge data_in or posedge r1) begin
    if (r1)
        q1_reg <= 1'b0;
    else
        q1_reg <= d1;
end

always @(posedge rst_n or posedge r2) begin
    if (r2)
        q2_reg <= 1'b0;
    else
        q2_reg <= d2;
end

always @(posedge rst_n or posedge r3) begin
    if (r3)
        q3_reg <= 1'b0;
    else
        q3_reg <= d3;
end

endmodule
